#!/bin/sh
# Writes Configuration/Version.xcconfig from version.properties and generates Vicu.xcodeproj.
# BUILD_ATTEMPT (default 0) is added to the build number, so the same version can be uploaded to
# TestFlight again without a new Android versionCode.
set -eu
cd "$(dirname "$0")/.."
props=../version.properties
name=$(sed -n 's/^versionName=//p' "$props" | tr -d '\r')
code=$(sed -n 's/^versionCode=//p' "$props" | tr -d '\r')
attempt=${BUILD_ATTEMPT:-0}
cat > Configuration/Version.xcconfig <<XC
// Generated by scripts/generate.sh from version.properties. Do not edit.
MARKETING_VERSION = $name
CURRENT_PROJECT_VERSION = $((code * 100 + attempt))
XC
xcodegen generate --quiet --spec project.yml
